  'demo.tour.ui.missing': '화면의 그 부분이 지금은 보이지 않습니다. ‘다음’으로 계속하세요. 그동안에도 제품은 마음껏 써 볼 수 있습니다.',
  'demo.tour.ui.endTitle': '방금 본 것이 진짜 제품입니다',
  'demo.tour.ui.endBody': '방금 본 모든 것이 가상의 데이터로 당신의 브라우저에서 돌아갔습니다. 계속 혼자 둘러보거나, 팀을 위한 워크스페이스를 시작하세요.',
  'demo.tour.ui.keep': '계속 둘러보기',
