  'demo.hub.title': '실제 제품으로 보는 가이드 투어 — Curahold',
  'demo.hub.description': '브라우저에서 실제 Curahold를 가상의 회사 데이터로 돌려 보는 짧은 가이드 투어. 역할에 맞게 고르세요: 갱신, 고객 헬스, 팀의 한 주, 리포트, CuraAI 등.',
