  'docs.edited': '마지막 업데이트',
  'docs.inEnglish': '이 페이지는 영어입니다. 개발자 페이지, API 레퍼런스, 릴리스 노트, 법적 문서는 영어로 제공합니다.',
  'docs.ask.open': '질문',
  'docs.ask.title': 'Curahold에 묻기',
  'docs.ask.close': '닫기',
  'docs.ask.hello': 'Curahold에서 무언가를 하는 방법을 평소 말투로 물어보세요. 이 문서에서 답을 찾아 출처와 함께 보여 드립니다.',
  'docs.ask.hi': '안녕하세요! Curahold에서 무엇을 하고 싶으세요?',
  'docs.ask.thanks': '도움이 되었다니 다행입니다. 언제든 또 물어보세요.',
  'docs.ask.empty': '하고 싶은 일을 몇 단어로 적어 주세요.',
  'docs.ask.placeholder': '고객을 어떻게 가져오나요?',
  'docs.ask.from': '출처',
  'docs.ask.more': '전체 보기',
  'docs.ask.also': '관련 항목',
  'docs.ask.unsure': '이게 맞는지 확실하지 않지만, 문서에서 가장 가까운 부분은 이렇습니다:',
  'docs.ask.none': '문서에서 찾지 못했습니다. 다른 말로 해 보시거나 지원팀에 문의하세요.',
  'docs.ask.support': '지원팀에 문의',
  'docs.ask.helped': '답이 되었나요?',
