  'trial.err.summary': "확인이 필요한 답변이 있습니다:",
  'trial.consent.title': "개인정보와 선택 사항",
  'trial.consent.notice': "이 정보의 이용 방법은 {law} 개인정보 처리 안내에 있습니다. 신청 검토, 관련 연락, 체험 준비에 사용합니다.",
  'trial.consent.capacity': "만 18세 이상이며 회사를 대표하여 이 신청을 합니다.",
  'trial.consent.processingAbroad': "Curahold가 위 목적을 위해 위 개인정보를 처리하고, 안내에 명시된 제공자가 국외에서 보관·처리하는 데 동의합니다. 언제든 동의를 철회할 수 있으며, 철회 시 신청을 처리할 수 없습니다({law}).",
  'trial.consent.trMarketing': "Curahold 마케팅 연락을 위해 제 신원 및 연락처 정보가 처리되는 데 명시적으로 동의합니다(KVKK).",
  'trial.consent.read': "안내 읽기",
  'trial.consent.processing': "Curahold가 체험 신청 검토와 관련 연락을 위해 이 양식의 정보를 처리하는 데 동의합니다({law}).",
  'trial.consent.transfer': "이 정보가 안내에 명시된 서비스 제공자에 의해 국외에서 보관·처리되는 데 동의합니다({law}).",
  'trial.consent.itemised': "개인정보 수집·이용 안내 · 수집 항목: 이름, 회사 이메일, 직함, 회사명, 국가 등 신청서에 입력한 정보 · 목적: 무료 체험 신청 검토, 신청 관련 연락, 체험 계정 개설 · 보유 기간: 체험이 시작되지 않으면 최대 12개월 · 근거: 「{law}」 제15조 제1항 제4호. 자세한 내용은 개인정보 처리방침에 있습니다.",
  'trial.consent.marketingEmail': "네, Curahold의 제품 소식과 혜택을 이메일로 받겠습니다. 언제든 수신을 거부할 수 있습니다.",
  'trial.consent.iysEmail': "Curahold가 제품·서비스에 관한 상업용 전자 메시지(홍보, 캠페인, 안내)를 제 이메일로 보내는 것을 승인합니다. 이 승인은 언제든 이유 없이 무료로 철회할 수 있습니다.",
  'trial.consent.lawGeneric': "개인정보",
  'trial.consent.required': "필수",
  'trial.consent.marketingNote': "선택 사항이며 신청과 별개입니다. 모든 이메일의 링크로 언제든 철회할 수 있습니다.",
  'trial.done.title': "감사합니다. 신청이 접수되었습니다",
  'trial.done.text': "접수 번호 {ref}. 모든 신청을 직접 검토하며, 보통 영업일 기준 하루 안에 {email}(으)로 연락드립니다.",
  'trial.done.demo': "그동안 라이브 데모를 둘러보세요",
  'trial.unsubscribe.title': "마케팅 메시지",
  'trial.unsubscribe.button': "마케팅 메시지 받지 않기",
  'trial.unsubscribe.done': "이제 Curahold의 마케팅 메시지를 받지 않습니다. 체험 신청 관련 메시지는 계속 받습니다.",
  'trial.unsubscribe.bad': "이 링크는 더 이상 작동하지 않습니다. 연락 주시면 직접 중지하겠습니다.",
  'email.trial.code.subject': "Curahold 인증 코드: {code}",
  'email.trial.code.body': "인증 코드는 {code}입니다. 체험 신청 양식에 입력해 주세요. {minutes}분 동안 유효합니다.\n\n요청하지 않으셨다면 이 메일을 무시하세요.",
  'email.trial.received.subject': "체험 신청을 받았습니다({ref})",
  'email.trial.received.body': "{name}님, 안녕하세요.\n\n신청해 주셔서 감사합니다. 모든 신청을 직접 검토하며, 보통 영업일 기준 하루 안에 연락드립니다.\n\n접수 번호: {ref}\n\n마케팅 메시지 수신 거부: {unsubscribe}",
  'email.trial.reminder.subject': "Curahold 체험이 {days}일 후 종료됩니다",
  'email.trial.reminder.body': "{name}님, 안녕하세요.\n\n{org}의 체험이 {days}일 후 종료됩니다. 끊김 없이 계속 쓰려면 요금제를 선택하세요: {link}\n\n선택하지 않아도 삭제되는 것은 없습니다. 회사는 읽기 전용이 되며, 모든 내용을 계속 보고 내보낼 수 있습니다.",
  'email.trial.lastDay.subject': "Curahold 체험이 내일 종료됩니다",
  'email.trial.lastDay.body': "{name}님, 안녕하세요.\n\n{org}의 체험이 내일 종료됩니다. 끊김 없이 계속 쓰려면 요금제를 선택하세요: {link}\n\n선택하지 않아도 삭제되는 것은 없습니다. 회사는 읽기 전용이 되며, 모든 내용을 계속 보고 내보낼 수 있습니다.",
  'email.trial.ended.subject': "Curahold 체험이 종료되었습니다. 삭제된 것은 없습니다",
  'email.trial.ended.body': "{name}님, 안녕하세요.\n\n{org}의 체험이 종료되었습니다. 회사는 이제 읽기 전용입니다. 삭제된 것은 없으며, 모든 내용을 보고 내보낼 수 있습니다. 다시 편집하려면 요금제를 선택하세요: {link}",
  'agreements.title': "시작하기 전에: 이용약관과 데이터 처리",
  'agreements.lead': "{org}의 체험이 승인되었습니다. 관리자로서 회사를 대표해 아래 두 문서에 동의해 주세요.",
  'agreements.terms': "이용약관",
  'agreements.dpa': "데이터 처리 계약(DPA)",
  'agreements.version': "버전 {version}",
  'agreements.open': "읽기",
  'agreements.statement': "회사를 대표하여 이용약관(버전 {terms})과 데이터 처리 계약(버전 {dpa})에 동의하며, 그럴 권한이 있습니다.",
  'email.agreements.subject': "사본: {org}의 Curahold 약관 및 DPA 동의 완료",
  'email.agreements.body': "{name}님, 안녕하세요.\n\n{at}(UTC)에 {org}를 대표하여 다음에 동의하셨습니다:\n\n{statement}\n\n이용약관 버전 {terms}: {termsLink}\n데이터 처리 계약 버전 {dpa}: {dpaLink}\n\n이 이메일을 사본으로 보관하세요. 모든 버전은 이 주소에서 계속 볼 수 있습니다.",
  'agreements.accept': "동의하고 계속",
  'agreements.waiting': "작업을 시작하기 전에 {org} 관리자가 약관에 동의해야 합니다. 동의가 끝나면 바로 들어갈 수 있습니다.",
  'agreements.draft': "법률 검토 중인 초안 문서입니다.",
  'audit.agreements.accepted': "이용약관과 DPA에 동의함",
  'errors.seat_cap_reached': "체험에 포함된 정규 좌석 {cap}개를 모두 쓰고 있습니다. 보기 전용으로 초대하거나(무료) 좌석 추가를 요청하세요.",
  'errors.terms_required': "먼저 이용약관과 DPA에 동의해 주세요. 관리자가 한 번의 클릭으로 할 수 있습니다.",
  'errors.free_mail_note': "회사 체험에 개인 주소를 쓰는 이유를 한 문장으로 알려 주세요.",
